[CmdletBinding()]
param([ValidateSet('preflight','receiver','sender')][string]$Role='preflight',[string]$Server=$env:LINKSEND_SERVER,[string]$Stun=$env:LINKSEND_STUN,[string]$Bind=$env:LINKSEND_BIND,[string]$DataDir=$env:LINKSEND_DATA_DIR,[string]$ReceiveDir=$env:LINKSEND_RECEIVE_DIR,[string]$Peer=$env:LINKSEND_PEER,[string[]]$File,[string]$Binary=$env:LINKSEND_BINARY,[switch]$SkipBuild)
$ErrorActionPreference='Stop'; if(!$Server){throw '请提供 -Server'}; if(!$DataDir){$DataDir='.stage2a/profile'}; $root=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path; Set-Location $root; $evidence=Join-Path $root ('.stage2a\'+(Get-Date -Format yyyyMMdd-HHmmss)); New-Item -ItemType Directory -Force $evidence,(Join-Path $root $DataDir) | Out-Null
function Run($n,[scriptblock]$b){&$b *>&1|Tee-Object (Join-Path $evidence "$n.log");if($LASTEXITCODE){throw "$n 失败"}}
if(!(Get-Command go -EA SilentlyContinue)){throw '未找到 Go'}; Run go-version {go version}; $u=[Uri]$Server; if($u.Host -match '^(localhost|127\.|::1)$'){throw '禁止 loopback 信令地址'}; Run dns {Resolve-DnsName $u.Host -Type A_AAAA -EA Stop}; if($SkipBuild){if(!$Binary){throw '-SkipBuild 必须提供 -Binary'}; $Binary=(Resolve-Path $Binary).Path}else{Run build {go build -trimpath -o (Join-Path $evidence 'linksend.exe') ./cmd/linksend}; $Binary=Join-Path $evidence 'linksend.exe'}; (Get-FileHash $Binary -Algorithm SHA256).Hash | Set-Content (Join-Path $evidence 'binary.sha256')
[ordered]@{role=$Role;server=$Server;stun=$Stun;bind=$Bind;started=(Get-Date).ToUniversalTime().ToString('o');host=$env:COMPUTERNAME}|ConvertTo-Json|Set-Content (Join-Path $evidence run.json) -Encoding utf8
if($Role -eq 'preflight'){Write-Host "预检完成: $evidence";exit 0}; if(!$Bind){throw '必须提供 -Bind'}; $common=@('--server',$Server,'--data-dir',(Resolve-Path $DataDir).Path)
if($Role -eq 'receiver'){if(!$ReceiveDir){throw 'receiver 必须提供 -ReceiveDir'};& $Binary @common receive --dir $ReceiveDir --bind $Bind --stun $Stun --evidence --auto-accept --wait-timeout 30m 1> (Join-Path $evidence result.json) 2> (Join-Path $evidence stderr.log)}else{if(!$Peer -or !$File){throw 'sender 必须提供 -Peer 和 -File'};& $Binary @common send --peer $Peer --bind $Bind --stun $Stun --evidence @File 1> (Join-Path $evidence result.json) 2> (Join-Path $evidence stderr.log)};if($LASTEXITCODE){throw '传输失败（result.json 保留失败证据）'};Write-Host "$Role 完成: $evidence"
